<?php $isAdmin=currentUser()['role']==='admin';$unread=array_filter($notifications,fn($item)=>empty($item['read_at']));?>
<div class="app-shell <?=$isAdmin?'admin-shell':''?>"><?php $active='notifications';require dirname(__DIR__).'/partials/sidebar.php';?><main class="workspace"><div class="workspace-content notifications-page"><header class="notifications-header"><div><span>Centre d’activité</span><h1>Notifications</h1><p>Retrouvez les événements importants liés à votre compte et à vos contenus.</p></div><?php if($unread):?><form method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="form" value="notifications_read_all"><button class="button secondary"><?=icon('check',16)?><span>Tout marquer comme lu</span></button></form><?php endif?></header><section class="notifications-card"><?php if($notifications):?><div class="notifications-meta"><strong><?=count($unread)?> non lue<?=count($unread)>1?'s':''?></strong><span><?=count($notifications)?> notification<?=count($notifications)>1?'s':''?></span></div><div class="notification-list"><?php foreach($notifications as $item):?><article class="notification-item <?=empty($item['read_at'])?'unread':''?>"><span class="notification-symbol <?=e($item['type'])?>"><?=icon($item['type']==='publication'?'upload':($item['type']==='welcome'?'user':'bell'),19)?></span><div class="notification-copy"><div><h2><?=e($item['title'])?></h2><?php if(empty($item['read_at'])):?><i>Nouveau</i><?php endif?></div><p><?=e($item['message'])?></p><time datetime="<?=e($item['created_at'])?>"><?=date('d/m/Y à H:i',strtotime($item['created_at']))?></time></div><?php if(empty($item['read_at'])||$item['link']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="form" value="notification_read"><input type="hidden" name="notification_id" value="<?=$item['id']?>"><input type="hidden" name="notification_link" value="<?=e($item['link'])?>"><button class="notification-open" aria-label="<?=empty($item['read_at'])?'Lire la notification':'Ouvrir le lien'?>"><?=icon($item['link']?'arrow':'check',17)?><span><?=$item['link']?'Ouvrir':'Marquer comme lue'?></span></button></form><?php endif?></article><?php endforeach?></div><?php else:?><div class="notifications-empty"><?=icon('bell',28)?><h2>Aucune notification</h2><p>Les nouvelles activités apparaîtront ici.</p></div><?php endif?></section></div></main></div>
